import {validActorScale,clampScaleAxis} from './transform-scale.js';
import {validGameJson} from './game-json.js';
const id=v=>typeof v==='string'&&v.length>0&&v.length<=160&&!/[\x00-\x1f]/.test(v);
const vector=(v,max,positive=false)=>Array.isArray(v)&&v.length===3&&v.every(x=>Number.isFinite(x)&&Math.abs(x)<=max&&(!positive||x>=.01));
export function validReplica(row){return !!row&&id(row.id)&&id(row.owner)&&Object.keys(row).every(k=>['id','owner','position','rotation','scale','visible','properties','spawn','relevancy','deleted'].includes(k))&&(row.deleted===undefined||row.deleted===true&&Object.keys(row).every(k=>['id','owner','deleted'].includes(k)))&&(row.position===undefined||vector(row.position,1000000))&&(row.rotation===undefined||vector(row.rotation,360000))&&(row.scale===undefined||validActorScale(row.scale))&&(row.visible===undefined||typeof row.visible==='boolean')&&(row.properties===undefined||validGameJson(row.properties)&&JSON.stringify(row.properties).length<=16384)&&(row.spawn===undefined||row.spawn&&Object.keys(row.spawn).every(k=>['asset','root','local'].includes(k))&&id(row.spawn.asset)&&id(row.spawn.root)&&id(row.spawn.local))&&(row.relevancy===undefined||row.relevancy&&Object.keys(row.relevancy).every(k=>['radius','ownerOnly'].includes(k))&&Number.isFinite(row.relevancy.radius)&&row.relevancy.radius>=0&&row.relevancy.radius<=1000000&&typeof row.relevancy.ownerOnly==='boolean');}
export const validInterest=position=>vector(position,1000000);
export function replicaSpawnCompatible(object,row){return !object.spawnRoot?!row.spawn:!!row.spawn&&row.spawn.root===object.spawnRoot&&row.spawn.asset===object.spawnAsset&&row.spawn.local===object.spawnLocalId;}
export function replicaRelevant(row,peer){if(peer.authority||row.owner===peer.id)return true;if(row.deleted)return true;if(row.relevancy?.ownerOnly)return false;const radius=row.relevancy?.radius||0;if(!radius||!row.position)return true;const position=peer.interest||[0,0,0];return row.position.reduce((n,v,i)=>n+(v-position[i])**2,0)<=radius*radius;}
export function validNetworkRPC(row){return !!row&&id(row.target)&&id(row.event)&&typeof row.multicast==='boolean'&&validGameJson(row.args)&&JSON.stringify(row.args).length<=16384;}
export function interpolateReplica(object,row,delta,speed=12){const blend=speed===0?1:1-Math.exp(-Math.max(0,delta)*speed);let changed=false;for(const key of ['position','rotation','scale'])if(row[key]){if(!object[key]){object[key]=[...row[key]];changed=true;}else for(let i=0;i<3;i++){let difference=row[key][i]-object[key][i];if(key==='rotation')difference=((difference+180)%360+360)%360-180;if(difference!==0){object[key][i]+=difference*(Math.abs(difference)<1e-6?1:blend);if(key==='scale')object[key][i]=clampScaleAxis(object[key][i]);changed=true;}}}if(row.visible!==undefined&&object.visible!==row.visible){object.visible=row.visible;changed=true;}return changed;}
